SELECT state.task_id FROM public_submission_delivery_state AS state JOIN retained_visible_public_submission_delivery AS visible ON visible.task_id = state.task_id WHERE (((state.status = 'pending' AND state.next_attempt_at <= unixepoch()) OR (state.status = 'leased' AND state.lease_expires_at <= unixepoch() AND state.next_attempt_at <= unixepoch())) AND state.attempt_count < 5 AND visible.created_at + 86400 > unixepoch()) OR (state.status = 'pending' AND visible.created_at + 86400 <= unixepoch()) OR (state.status = 'leased' AND state.lease_expires_at <= unixepoch() AND (state.attempt_count >= 5 OR visible.created_at + 86400 <= unixepoch())) ORDER BY state.next_attempt_at, visible.created_at, visible.task_id LIMIT 1
